export function original(value) { return value + "!"; }
original.label = "first";
Object.defineProperty(original, "info", { get() { return this === original ? "same" : "wrong"; }, enumerable: true });
const before = original;
function factory() { return original; }
export const exposed = factory();
export function same() { return exposed === before; }
export function change() { exposed.label = "changed"; return original.label; }
